// Advanced, deterministic delivery-quality analysis: filler words, pace, turn tracking.
const cfg = $('Set - Config').first().json;
const sttResponse = $input.first().json;

const transcript = String(sttResponse.text || sttResponse.transcript || '').trim();
const durationSeconds = sttResponse.duration || sttResponse.duration_seconds || null;

const words = transcript.length ? transcript.split(/\s+/).filter(Boolean) : [];
const wordCount = words.length;

const FILLER_WORDS = ['um', 'uh', 'uhh', 'umm', 'like', 'you know', 'sort of', 'kind of', 'basically', 'actually'];
let fillerCount = 0;
const lowerTranscript = transcript.toLowerCase();
for (const filler of FILLER_WORDS) {
  const escaped = filler.replace(/\s+/g, '\\s+');
  const re = new RegExp('\\b' + escaped + '\\b', 'g');
  const matches = lowerTranscript.match(re);
  if (matches) fillerCount += matches.length;
}
const fillerRatio = wordCount > 0 ? fillerCount / wordCount : 0;

let paceWpm = null;
let paceAssessment = 'unknown';
if (durationSeconds && durationSeconds > 0 && wordCount > 0) {
  paceWpm = Math.round((wordCount / durationSeconds) * 60);
  if (paceWpm < 110) paceAssessment = 'too slow';
  else if (paceWpm > 170) paceAssessment = 'too fast';
  else paceAssessment = 'good pace';
}

// Advance the turn counter and decide whether this is the final turn
const turnNumber = (cfg.turnNumber || 0) + 1;
const maxTurns = cfg.maxTurns || 6;
const isFinalTurn = turnNumber >= maxTurns;

const coachingNotes = [];
if (fillerRatio > 0.05) {
  coachingNotes.push('High filler-word usage (' + Math.round(fillerRatio * 100) + '% of words) — try a silent pause instead.');
}
if (paceAssessment === 'too fast') {
  coachingNotes.push('Speaking pace (' + paceWpm + ' wpm) is on the fast side — slow down for clarity.');
}
if (paceAssessment === 'too slow') {
  coachingNotes.push('Speaking pace (' + paceWpm + ' wpm) is on the slow side — a bit more energy could help.');
}
if (wordCount < 15) {
  coachingNotes.push('Answer is quite short — consider elaborating with a specific example (STAR format).');
}

return [{
  json: {
    ...cfg,
    transcript,
    wordCount,
    fillerCount,
    fillerRatio: Math.round(fillerRatio * 1000) / 1000,
    paceWpm,
    paceAssessment,
    turnNumber,
    isFinalTurn,
    coachingNotes
  }
}];

